  {id:'1954',years:'1954 — 1975',title:'HƯỚNG TỚI THỐNG NHẤT',short:'Hai miền, một mục tiêu: hòa bình và thống nhất đất nước.',sessions:'Buổi 15–18',intro:'Miền Bắc xây dựng chủ nghĩa xã hội và làm hậu phương; miền Nam tiếp tục đấu tranh giải phóng, tiến tới thống nhất.',points:['1954–1965: lãnh đạo cách mạng hai miền Nam – Bắc.','1965–1975: kháng chiến chống Mỹ, cứu nước trên phạm vi cả nước.','30/4/1975: Chiến dịch Hồ Chí Minh toàn thắng.']},
  {id:'1975',years:'1975 — 1986',title:'XÂY DỰNG & TÌM ĐƯỜNG',short:'Xây dựng đất nước sau chiến tranh và tìm bước đột phá.',sessions:'Buổi 19–21',intro:'Sau thống nhất, đất nước bước vào thời kỳ xây dựng chủ nghĩa xã hội và bảo vệ Tổ quốc, đồng thời nhận diện những khó khăn, hạn chế để tìm hướng đổi mới.',points:['1975–1981: xây dựng chủ nghĩa xã hội và bảo vệ Tổ quốc.','12/1976: Đại hội IV, Đảng Lao động Việt Nam đổi tên thành Đảng Cộng sản Việt Nam.','1982–1986: Đại hội V và các bước tìm tòi, đổi mới kinh tế.']},
  {id:'1986',years:'1986 — NAY',title:'ĐỔI MỚI & HỘI NHẬP',short:'Đổi mới toàn diện, công nghiệp hóa và hội nhập quốc tế.',sessions:'Buổi 22–29',intro:'Đại hội VI mở đầu công cuộc Đổi mới. Những đại hội sau tiếp tục định hình hướng phát triển kinh tế, công nghiệp hóa, hiện đại hóa và hội nhập.',points:['12/1986: Đại hội VI đề ra đường lối đổi mới toàn diện.','1991: Đại hội VII thông qua Cương lĩnh xây dựng đất nước trong thời kỳ quá độ lên chủ nghĩa xã hội.','Từ 1996: tiếp tục công nghiệp hóa, hiện đại hóa và hội nhập quốc tế.']}
